import {
  Box,
  Container,
  createTheme,
  Grid,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import bgImg from "../../../assets/images/aboutusBGImg.png";
import visionIcon from "../../../assets/images/vision.svg";
import visionIconSmall from "../../../assets/images/visionSmall.svg";
import ScrollAnimation from "react-animate-on-scroll";
import { useState } from "react";
import { useEffect } from "react";
import { useRef } from "react";

const Vision = () => {
  const [scrollPosition, setScrollPosition] = useState(0);
  const [hasTriggered, setHasTriggered] = useState(false);
  const containerRef = useRef(null);

  const handleScroll = () => {
    if (!hasTriggered) {
      const position = window.pageYOffset;
      setScrollPosition(position);
    }
  };

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasTriggered) {
          setHasTriggered(true);
          handleScroll(); // Ensure to capture initial scroll position
        }
      },
      { threshold: 0.1 } // Adjust threshold as needed
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        observer.unobserve(containerRef.current);
      }
    };
  }, [hasTriggered]);

  useEffect(() => {
    if (!hasTriggered) {
      window.addEventListener("scroll", handleScroll);
    }
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [hasTriggered]);

  const bgPositionX = hasTriggered ? Math.min(scrollPosition / 3, 100) : 0;
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  return (
    <>
      <Box
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 56 },
          py: { xs: 8, sm: 10, lg: 15 },
        }}
      >
        <Container
          maxWidth={"xl"}
          ref={containerRef}
          sx={{
            backgroundColor: "#F6F8F8",
            borderRadius: { xs: "16px", sm: "60px" },
            backgroundImage: { sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `${bgPositionX}% top`, // Update background position dynamically
            transition: "background-position 4s ease-out", // Smooth transition
          }}
        >
          <Grid container sx={{ p: { xs: 3, sm: 10 } }} rowSpacing={3}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                gap: 2,
                alignItems: { xs: "center", sm: "start" },
              }}
            >
              <Box
                sx={{
                  backgroundColor: "#E2EBE9",
                  height: { xs: "48px", sm: "72px" },
                  width: { xs: "48px", sm: "72px" },
                  borderRadius: { xs: "8px", sm: "16px" },
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {isMobile ? (
                  <img src={visionIconSmall} />
                ) : (
                  <img src={visionIcon} />
                )}
              </Box>
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",
                      sm: "35px",
                      md: "40px",
                      lg: "46px",
                    },
                    lineHeight: { xs: "34px", lg: "55px" },
                    fontWeight: 500,
                    color: "#201D28",
                  }}
                >
                  Vision
                </Typography>
              </ScrollAnimation>
            </Grid>
            <Grid item xs={12}>
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: { xs: "14px", lg: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "22px", lg: "30px" },
                    color: "#646271",
                    textAlign: "justify",
                  }}
                >
                  To be the leading catalyst for digital transformation in Oman,
                  empowering businesses and government entities with innovative
                  IT management solutions. We envision a technologically
                  advanced Oman where seamless integration of digital
                  technologies enhances productivity, drives economic growth,
                  and enriches the quality of life for all citizens. By 2040,
                  our company will be at the forefront of the digital
                  revolution, fostering a culture of continuous innovation,
                  excellence, and sustainable development. Our commitment to
                  leveraging cutting-edge technologies, fostering local talent,
                  and adhering to the highest standards of service will position
                  us as the trusted partner in Oman's journey towards a
                  digitally empowered future.
                </Typography>
              </ScrollAnimation>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default Vision;
