import {
  Container,
  Grid,
  Typography,
  Box,
  IconButton,
  createTheme,
  useMediaQuery,
} from "@mui/material";
import React, { useRef } from "react";
import OurMilestoneSwiper from "./OurMilestoneSwiper";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import { useEffect } from "react";
import { useState } from "react";
import ScrollAnimation from "react-animate-on-scroll";

const OurMilestone = () => {
  const swiperRef = useRef(null);
  const [isBeginning, setIsBeginning] = useState(true);
  const [isEnd, setIsEnd] = useState(false);

  const setSwiperRef = (ref) => {
    swiperRef.current = ref.current;
    if (swiperRef.current) {
      swiperRef.current.swiper.on("slideChange", () => {
        setIsBeginning(swiperRef.current.swiper.isBeginning);
        setIsEnd(swiperRef.current.swiper.isEnd);
      });
    }
  };
  useEffect(() => {
    if (swiperRef.current) {
      setIsBeginning(swiperRef.current.swiper.isBeginning);
      setIsEnd(swiperRef.current.swiper.isEnd);
    }
  }, []);
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.up("sm"));
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 5, sm: 10, lg: 15, xl: 20 },
            pt: { xs: 10, sm: 8 },
          }}
        >
          <Grid container rowSpacing={{ xs: 5, sm: 10, md: 13 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                justifyContent: { xs: "center", sm: "space-between" },
              }}
            >
              <Box>
                <ScrollAnimation animateIn="fade-in-left " animateOnce>
                  {" "}
                  <Typography
                    sx={{
                      fontSize: {
                        xs: "26px",
                        sm: "36px",
                        md: "46px",
                        lg: "56px",
                      },
                      fontWeight: 500,
                      lineHeight: {
                        xs: "30px",
                        sm: "40px",
                        md: "50px",
                        lg: "70px",
                      },
                      color: "#201D28",
                    }}
                  >
                    Our Milestone
                  </Typography>
                </ScrollAnimation>
              </Box>
              {isMobile && (
                <Box sx={{ display: "flex", alignItems: "end" }}>
                  <IconButton
                    sx={{
                      "&:hover": {
                        backgroundColor: "transparent",
                      },
                      color: isBeginning ? "#BAB6C6" : "#000000",
                    }}
                    onClick={() => swiperRef.current?.swiper.slidePrev()}
                  >
                    <ArrowBackIcon />
                  </IconButton>
                  <IconButton
                    sx={{
                      "&:hover": {
                        backgroundColor: "transparent",
                      },
                      color: isEnd ? "#BAB6C6" : "#000000",
                    }}
                    onClick={() => swiperRef.current?.swiper.slideNext()}
                  >
                    <ArrowForwardIcon />
                  </IconButton>
                </Box>
              )}
            </Grid>
            <Grid item xs={12}>
              <OurMilestoneSwiper setSwiperRef={setSwiperRef} />
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default OurMilestone;
