import {
  Box,
  Container,
  createTheme,
  Grid,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import bgImg from "../../../assets/images/aboutusBGImg.png";
import valuesIcon from "../../../assets/images/values.svg";
import valuesIconSmall from "../../../assets/images/valuesSmall.svg";
import ScrollAnimation from "react-animate-on-scroll";
import { useState } from "react";
import { useEffect } from "react";
import { useRef } from "react";

const values = [
  "Innovation: We embrace cutting-edge technologies and creative solutions to drive digital transformation and stay ahead in the dynamic IT landscape.",
  "Excellence: We strive for the highest standards in everything we do, delivering exceptional quality and value to our clients.",
  "Integrity: We conduct our business with transparency, honesty, and ethical practices, building lasting trust with our clients and partners.",
  " Customer-Centricity: We prioritize our clients' needs, delivering personalized solutions and exceptional service to ensure their success and satisfaction.",
  "Collaboration: We believe in the power of teamwork and partnership, working closely with clients, partners, and stakeholders to achieve common goals.",
  "Sustainability: We are committed to sustainable practices that support Oman's economic, social, and environmental well-being.",
  "Continuous Improvement: We foster a culture of learning and growth, encouraging our team to develop their skills and adapt to the evolving digital landscape.",
  "Community Engagement: We are dedicated to contributing positively to the communities we serve, promoting digital literacy and supporting local initiatives.",
];
const Values = () => {
  const [scrollPosition, setScrollPosition] = useState(0);
  const [hasTriggered, setHasTriggered] = useState(false);
  const containerRef = useRef(null);

  const handleScroll = () => {
    if (!hasTriggered) {
      const position = window.pageYOffset;
      setScrollPosition(position);
    }
  };

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasTriggered) {
          setHasTriggered(true);
          handleScroll(); // Ensure to capture initial scroll position
        }
      },
      { threshold: 0.1 } // Adjust threshold as needed
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        observer.unobserve(containerRef.current);
      }
    };
  }, [hasTriggered]);

  useEffect(() => {
    if (!hasTriggered) {
      window.addEventListener("scroll", handleScroll);
    }
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, [hasTriggered]);

  const bgPositionX = hasTriggered ? Math.min(scrollPosition / 3, 100) : 0;
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  return (
    <>
      <Box
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 56 },
          pb: { xs: 5, lg: 5, xl: 0 },
        }}
      >
        <Container
          maxWidth={"xl"}
          ref={containerRef}
          sx={{
            backgroundColor: "#F5F5F9",
            borderRadius: { xs: "16px", sm: "60px" },
            backgroundImage: { sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: `${bgPositionX}% top`, // Update background position dynamically
            transition: "background-position 4s ease-out", // Smooth transition
          }}
        >
          <Grid container sx={{ p: { xs: 3, sm: 10 } }} rowSpacing={3}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                gap: 2,
                alignItems: { xs: "center", sm: "start" },
              }}
            >
              <Box
                sx={{
                  backgroundColor: "#E5E3ED",
                  height: { xs: "48px", sm: "72px" },
                  width: { xs: "48px", sm: "72px" },
                  borderRadius: { xs: "8px", sm: "16px" },
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {isMobile ? (
                  <img src={valuesIconSmall} />
                ) : (
                  <img src={valuesIcon} />
                )}
              </Box>
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                {" "}
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",
                      sm: "35px",
                      md: "40px",
                      lg: "46px",
                    },
                    lineHeight: { xs: "34px", lg: "55px" },
                    fontWeight: 500,
                    color: "#201D28",
                  }}
                >
                  Values
                </Typography>
              </ScrollAnimation>
            </Grid>
            <Grid item xs={12}>
              {values.map((item, index) => (
                <ScrollAnimation
                  animateIn="fadeIn"
                  animateOut="fadeOut"
                  key={index}
                >
                  <Typography
                    sx={{
                      fontSize: { xs: "14px", lg: "18px" },
                      fontWeight: 500,
                      lineHeight: { xs: "22px", lg: "30px" },
                      color: "#646271",
                      textAlign: "justify",
                    }}
                  >
                    {index + 1}. {item}
                  </Typography>
                </ScrollAnimation>
              ))}
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: { xs: "14px", lg: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "22px", lg: "30px" },
                    color: "#646271",
                    textAlign: "justify",
                  }}
                >
                  By upholding these values, we aim to be the leading force in
                  Oman's digital transformation, driving innovation and
                  excellence in IT management solutions.
                </Typography>
              </ScrollAnimation>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default Values;
