import {
  Box,
  Container,
  createTheme,
  Grid,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React from "react";
import bgImg from "../../../assets/images/aboutusBGImg.png";
import missionIcon from "../../../assets/images/mission.svg";
import missionIconSmall from "../../../assets/images/missionSmall.svg";
import ScrollAnimation from "react-animate-on-scroll";
import { useState } from "react";
import { useEffect } from "react";
import { useRef } from "react";

const missions = [
  "Driving Excellence: Providing top-tier IT services that enhance operational efficiency and productivity for businesses and government entities.",
  "Fostering Innovation: Continuously exploring and implementing cutting-edge technologies to stay ahead in the rapidly evolving digital landscape.",
  "Developing Talent: Investing in the growth and development of local talent, fostering a skilled workforce capable of leading Oman's digital future.",
  "Ensuring Sustainability: Promoting sustainable practices in all our operations to support Oman's long-term economic and environmental goals.",
  "Building Trust: Upholding the highest standards of integrity, reliability, and customer satisfaction to be the trusted partner in Oman's journey to a digitally advanced society.",
];
const Mission = () => {
  // const [scrollPosition, setScrollPosition] = useState(0);

  // const handleScroll = () => {
  //   const position = window.pageYOffset;
  //   setScrollPosition(position);
  // };

  // useEffect(() => {
  //   window.addEventListener("scroll", handleScroll);
  //   return () => {
  //     window.removeEventListener("scroll", handleScroll);
  //   };
  // }, []);

  // const bgPositionX = Math.min(scrollPosition / 3, 100); // Adjust the divisor to control speed
  const [isInView, setIsInView] = useState(false);
  const ref = useRef(null);

  const handleScroll = () => {
    if (ref.current) {
      const rect = ref.current.getBoundingClientRect();
      const windowHeight =
        window.innerHeight || document.documentElement.clientHeight;
      const isVisible = rect.top <= windowHeight && rect.bottom >= 0;

      if (isVisible) {
        setIsInView(true);
        window.removeEventListener("scroll", handleScroll); // Remove event listener after triggering
      }
    }
  };

  useEffect(() => {
    window.addEventListener("scroll", handleScroll);
    handleScroll(); // Check on mount

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  return (
    <>
      <Box
        sx={{
          px: { xs: 5, sm: 10, lg: 15, xl: 56 },
          pt: { xs: 12, lg: 9, xl: 3 },
        }}
        ref={ref}
      >
        <Container
          maxWidth={"xl"}
          sx={{
            backgroundColor: "#F5F5F9",
            borderRadius: { xs: "16px", sm: "60px" },
            backgroundImage: { sm: `url(${bgImg})` },
            backgroundRepeat: "no-repeat",
            backgroundPosition: isInView ? "top right " : "top left ",
            transition: "background-position 2s ease",
            ...(isInView && {
              backgroundPosition: "top right ",
              animation: "slideIn 5s forwards",
            }),
          }}
        >
          <Grid container sx={{ p: { xs: 3, sm: 10 } }} rowSpacing={3}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                gap: 2,
                alignItems: { xs: "center", sm: "start" },
              }}
            >
              <Box
                sx={{
                  backgroundColor: "#E5E3ED",
                  height: { xs: "48px", sm: "72px" },
                  width: { xs: "48px", sm: "72px" },
                  borderRadius: { xs: "8px", sm: "16px" },
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {isMobile ? (
                  <img src={missionIconSmall} />
                ) : (
                  <img src={missionIcon} />
                )}
              </Box>
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: {
                      xs: "26px",
                      sm: "35px",
                      md: "40px",
                      lg: "46px",
                    },
                    lineHeight: { xs: "34px", lg: "55px" },
                    fontWeight: 500,
                    color: "#201D28",
                  }}
                >
                  Mission
                </Typography>
              </ScrollAnimation>
            </Grid>
            <Grid item xs={12}>
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: { xs: "14px", lg: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "22px", lg: "30px" },
                    color: "#646271",
                    textAlign: "justify",
                  }}
                >
                  To empower Oman's digital transformation through innovative IT
                  management solutions, delivering exceptional value to our
                  clients by integrating advanced technologies and industry best
                  practices. We are dedicated to:
                </Typography>
              </ScrollAnimation>

              {missions.map((item, index) => (
                <ScrollAnimation
                  animateIn="fadeIn"
                  animateOut="fadeOut"
                  key={index}
                >
                  <Typography
                    sx={{
                      fontSize: { xs: "14px", lg: "18px" },
                      fontWeight: 500,
                      lineHeight: { xs: "22px", lg: "30px" },
                      color: "#646271",
                      textAlign: "justify",
                    }}
                  >
                    {index + 1}. {item}
                  </Typography>
                </ScrollAnimation>
              ))}
              <ScrollAnimation animateIn="fadeIn" animateOut="fadeOut">
                <Typography
                  sx={{
                    fontSize: { xs: "14px", lg: "18px" },
                    fontWeight: 500,
                    lineHeight: { xs: "22px", lg: "30px" },
                    color: "#646271",
                    textAlign: "justify",
                  }}
                >
                  Through our unwavering commitment to these principles, we aim
                  to contribute significantly to the realization of Oman's
                  Vision 2040, driving progress and prosperity for the nation.
                </Typography>
              </ScrollAnimation>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default Mission;
